-- D-19 Internal Audit Program: FSQM-038 and FRM-010 Internal Audit Record, both DRAFT.
--
-- Two Minor findings: 2.5.4.1 and 2.5.4.2 ("has not developed or implemented an Internal Audit Program").
-- FSQM-038 is reserved for D-19 in the remediation workbook. FRM-010 is the next free FRM-0xx number;
-- FRM-008 is deliberately never used (see FSQM-017 / D-18).
--
-- Owner's answers, 2026-09-30: cross-audit in-house (the SQF Practitioner and Senior Site Management each
-- audit what the other runs - full independence is not practical with three people, and 2.5.4.2 only asks
-- for it "where practical"); the whole Code spread over four quarterly audits; findings recorded in the app,
-- one line per sub-section with its evidence, non-conformances to FRM-007 (source "Internal audit").
-- Auditor training is still to be decided. The verification schedule row 'internal_audit' stays planned
-- until issue. The controlled document names positions only.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-038', 'FRM-010')) then
    raise exception 'FSQM-038 or FRM-010 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FSQM-009', 'FRM-007', 'FSQM-017', 'FSQM-012', 'FRM-913', 'FSQM-005', 'FRM-001', 'FSQM-004', 'FRM-952', 'FSQM-013', 'FSQM-018', 'SOP-2.2.3') and status = 'active') <> 12 then
    raise exception 'a document D-19 names is missing or not active.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-038', 'Internal Audit Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.5.4.1, 2.5.4.2, 2.5.4.4', true, $q${"purpose": "This program states how Adventure Bakery audits its own SQF System: what is audited and when, who audits it, how the evidence is recorded, and how what is found gets corrected and reported. Every applicable requirement of the SQF Food Safety Code: Food Manufacturing is audited at least once a year.", "scope": "The whole SQF System - the System Elements (2.1 to 2.9) and the Good Manufacturing Practices of Module 11 (11.1 to 11.8) of the SQF Food Safety Code: Food Manufacturing, Edition 9. The internal audit does not replace the GMP inspections of the site and equipment (FRM-913 under FSQM-012), the CCP record reviews or the other activities on the verification schedule in FSQM-017. It checks that those are being done and that they work.", "definitions": "Internal audit: a planned check, by the site's own people, that the site does what its SQF System documents say and that this meets the Code.\nSQF checklist: every clause of the Code, listed one by one. The site uses the System Elements and Module 11 tabs of its SQF gap assessment workbook.\nObjective evidence: what the auditor actually saw - a record, a document, the work on the floor, or the answer of the person doing it.\nNon-conformance: a requirement the site does not meet. Minor - not likely to lead to unsafe food. Major - likely to lead to unsafe food, or a requirement not being done at all.\nIndependent: the auditor does not carry out, day to day, the work being audited.", "responsibility": "Senior Site Management - approves this program; audits the sections the SQF Practitioner and production run day to day; receives every audit's results and signs FRM-010 to confirm it; makes sure the corrective actions are resourced.\nSQF Practitioner - owns this program and keeps the audit plan on schedule; audits the sections Senior Site Management runs day to day; makes sure every non-conformance is raised on FRM-007 and closed.\nAction owners - carry out the corrective and preventive actions assigned to them on FRM-007.\nAll staff - answer the auditor's questions and show them the records and the work.", "procedure": ["The audit plan", "• Every applicable requirement of the SQF Food Safety Code: Food Manufacturing is audited in every calendar year. The work is spread over four quarterly audits, so each one is a manageable piece of work for a small team (SQF 2.5.4.1):", "◦ Q1 (January to March): 2.1 Management commitment, 2.2 Document control and records, 2.3 Specifications and supplier approval, 2.9 Training, 11.8 Waste disposal.", "◦ Q2 (April to June): 2.4 Food safety system, 2.8 Allergen management, 11.3 Personnel hygiene and welfare, 11.4 Personnel processing practices.", "◦ Q3 (July to September): 2.5 SQF System verification, 2.6 Traceability, withdrawal, recall and crisis, 2.7 Food defense and food fraud, 11.1 Site location and premises, 11.2 Site operation - maintenance, calibration, pest prevention, cleaning.", "◦ Q4 (October to December): 11.5 Water, ice and air, 11.6 Receipt, storage and transport, 11.7 Separation of functions and foreign matter.", "• A quarter's audit can be done in one sitting or over several days within the quarter.", "• A quarter that is missed is audited in the next quarter together with that quarter's own sections, and the reason is written on FRM-010. No section goes unaudited for more than twelve months.", "• A section can be moved to another quarter - for example, to audit a program soon after it is issued - with Senior Site Management's approval written on FRM-010, as long as every section is still audited in the calendar year.", "• A section is audited again early when something suggests it is not working: repeated complaints, a CCP deviation, a failed trace test, or a finding at a certification or regulatory audit.", "Who audits", "• The site has too few people for an auditor who is independent of everything. So each section is audited by whichever of the SQF Practitioner and Senior Site Management does not carry out that work day to day (SQF 2.5.4.2):", "◦ Senior Site Management audits what the SQF Practitioner and production run: 2.4, 2.5, 2.6, 2.8, 11.2.5 (cleaning and sanitation), 11.3, 11.4, 11.6, 11.7 and 11.8.", "◦ The SQF Practitioner audits what Senior Site Management runs: 2.1, 2.2, 2.3, 2.7, 2.9, 11.1, 11.2 (apart from 11.2.5) and 11.5.", "• Where an auditor finds work of their own in the section being audited - for example, the SQF Practitioner prepares the documents audited under 2.2 - they say so on FRM-010, and Senior Site Management reviews that part of the evidence before signing the entry. Nobody signs off their own work as compliant unseen.", "• Both auditors are trained in internal audit before their first audit, and the training is recorded on FRM-952 (SQF 2.5.4.2).", "Carrying out an audit", "• The auditor opens an FRM-010 entry for the quarter and lists the sections to be audited. They take the clauses from the SQF checklist - the clause-by-clause System Elements and Module 11 tabs of the site's SQF gap assessment workbook - so that every requirement in those sections is covered (SQF 2.5.4.1 i).", "• Before starting, the auditor reads the findings from the last audit of those sections and the CAPAs that closed them, and checks during the audit that those actions have held.", "• For each sub-section - for example 2.4.3 Food Safety Plan - the auditor reads the requirement and what the site's documents say, then checks what actually happens: the records, the work on the floor, and the answers of the person who does it.", "• Each sub-section is one line on FRM-010, with the result and the objective evidence seen: which record (form number and date or lot), which document, what was observed, who was asked. A line marked Compliant with no evidence is not an audit result (SQF 2.5.4.1 ii).", "• A non-conformance gets its own line against the exact clause, with the evidence that shows it. Minor: a gap that is not likely to lead to unsafe food. Major: a gap that is likely to, or a requirement that is not being done at all.", "• A requirement that does not apply to the site is marked Not applicable with the reason - for example 11.5.4, no ice is used (FSQM-013).", "• If the auditor finds product at risk, it is dealt with at once - held under FSQM-018 - and not left for the report.", "Corrective and preventive action", "• Every non-conformance is raised on FRM-007 with the source 'Internal audit' within five working days of the audit, and the FRM-007 number is written on its FRM-010 line (SQF 2.5.4.1 iii, 2.5.4.4).", "• The CAPA is handled under FSQM-009: cause, correction, preventive action, owner, due date and a check that it worked. A major non-conformance is corrected within 14 days and a minor one within 30 days, the periods a certification audit allows. Where the full action takes longer, a temporary control is put in place and the plan is written on FRM-007.", "• Where a correction changes a document or the way the site makes safe food, the affected parts of the SQF System are reviewed as FSQM-009 requires (SQF 2.5.4.4).", "• The next audit of that section checks that the action has held.", "Reporting the results", "• The auditor signs FRM-010 and gives the results to Senior Site Management within five working days of the audit. Senior Site Management signs the entry to confirm they have received the results and the CAPAs raised (SQF 2.5.4.1 iv).", "• The results are told to the staff responsible for carrying out and verifying each corrective action, and FRM-010 records who was told and when (SQF 2.5.4.1 iv).", "• The year's audit results are an input to the annual management review on FRM-001 under FSQM-005.", "Records", "• FRM-010 entries, the FRM-007 CAPAs raised from them and the auditors' training on FRM-952 are kept for at least two years, as SOP-2.2.3 requires (SQF 2.5.4.4)."], "form_references": "FRM-010 - Internal Audit Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report\nFRM-952 - Training Competency Verification Record\nFRM-001 - Management Review", "records": "• FRM-010 entries, one per quarterly audit, with the evidence for every sub-section audited\n• FRM-007 CAPAs raised from internal audits\n• The auditors' internal audit training on FRM-952", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.5.4.1 and 2.5.4.2 (Internal Audits), 2.5.4.4 (records and CAPA from internal audits).\n\nFSQM-009 CAPA Program - corrective and preventive action.\nFSQM-017 Validation and Verification Program - the verification schedule.\nFSQM-012 GMP Program and FRM-913 - the regular GMP inspections (2.5.4.3).\nFSQM-005 Management Review.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here.\nSOP-2.2.3 Document and Record Control Program - retention.", "revision_history": "New - 2026-09-30 - DRAFT under D-19, for the two Minor findings against 2.5.4.1 and 2.5.4.2 ('Adventure Bakery has not developed or implemented an Internal Audit Program').\n\nOWNER'S DECISIONS (2026-09-30): cross-audit in-house - the SQF Practitioner and Senior Site Management each audit what the other runs, because full independence is not practical with three people; the audit is spread over the year, by quarter, rather than done in one sitting; findings are recorded in the Team Portal on FRM-010, one line per sub-section with its evidence, and non-conformances go to FRM-007.\n\nAT ISSUE: activate the 'internal_audit' row on the verification schedule (FSQM-017 Part 6) against FRM-010, every 3 months, so the Team Portal raises each quarter's audit.\n\nTO CONFIRM BEFORE ISSUE: (1) the auditors' training - a recognised internal auditor course, or in-house training signed off on FRM-952; (2) the split of sections between the two auditors in 'Who audits'; (3) when the first certification audit is expected - if it is less than a year away, the sections not yet audited must be brought forward so the whole Code has been audited before it. The first quarterly audit is Q4 2026 (11.5, 11.6, 11.7)."}$q$::jsonb),
  ('FRM-010', 'Internal Audit Record', 'form', 'Module 2', 'draft', 'New',
   '2.5.4.1, 2.5.4.2', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{audit_year} {quarter} internal audit"}, "sections": [{"id": "audit", "title": "1. The audit", "fields": [{"id": "how_this_works", "type": "info", "label": "How to fill this in", "text": "One entry per quarterly audit. Work from the SQF checklist for the sections below and write one line per sub-section (for example 2.4.3) with the evidence you saw. A non-conformance gets its own line against the exact clause and goes on FRM-007."}, {"id": "audit_plan", "type": "reference_table", "label": "Audit plan (FSQM-038) - sections and who audits them", "columns": ["Quarter", "Sections - audited by"], "rows": [["Q1 (January to March)", "2.1 Management commitment - SQF Practitioner; 2.2 Document control and records - SQF Practitioner; 2.3 Specifications and supplier approval - SQF Practitioner; 2.9 Training - SQF Practitioner; 11.8 Waste disposal - Senior Site Management"], ["Q2 (April to June)", "2.4 Food safety system - Senior Site Management; 2.8 Allergen management - Senior Site Management; 11.3 Personnel hygiene and welfare - Senior Site Management; 11.4 Personnel processing practices - Senior Site Management"], ["Q3 (July to September)", "2.5 SQF System verification - Senior Site Management; 2.6 Traceability, withdrawal, recall and crisis - Senior Site Management; 2.7 Food defense and food fraud - SQF Practitioner; 11.1 Site location and premises - SQF Practitioner; 11.2 Site operation - maintenance, calibration, pest prevention, cleaning - SQF Practitioner (11.2.5 Cleaning: Senior Site Management)"], ["Q4 (October to December)", "11.5 Water, ice and air - SQF Practitioner; 11.6 Receipt, storage and transport - Senior Site Management; 11.7 Separation of functions and foreign matter - Senior Site Management"]]}, {"id": "audit_year", "type": "text", "label": "Year", "width": "third", "required": true, "showInList": true}, {"id": "quarter", "type": "select", "label": "Quarter", "width": "third", "required": true, "showInList": true, "options": ["Q1 (January to March)", "Q2 (April to June)", "Q3 (July to September)", "Q4 (October to December)"]}, {"id": "audit_date", "type": "date", "label": "Audit date", "width": "third", "required": true, "showInList": true, "help": "The first day, if it ran over several days"}, {"id": "sections", "type": "select", "multiple": true, "label": "Sections audited", "required": true, "options": ["2.1 Management commitment", "2.2 Document control and records", "2.3 Specifications and supplier approval", "2.9 Training", "11.8 Waste disposal", "2.4 Food safety system", "2.8 Allergen management", "11.3 Personnel hygiene and welfare", "11.4 Personnel processing practices", "2.5 SQF System verification", "2.6 Traceability, withdrawal, recall and crisis", "2.7 Food defense and food fraud", "11.1 Site location and premises", "11.2 Site operation - maintenance, calibration, pest prevention, cleaning", "11.5 Water, ice and air", "11.6 Receipt, storage and transport", "11.7 Separation of functions and foreign matter"]}, {"id": "plan_change", "type": "textarea", "label": "Sections moved or carried over", "help": "Only if this audit is not the plan above: which sections were moved or carried over from a missed quarter, and why. Moving a section needs Senior Site Management's approval."}, {"id": "independence", "type": "select", "label": "Independence", "required": true, "options": ["The auditor does not do the audited work day to day", "The auditor did some of the audited work - listed below, reviewed by Senior Site Management"]}, {"id": "independence_note", "type": "textarea", "label": "Audited work the auditor did themselves"}]}, {"id": "findings_section", "title": "2. Findings", "fields": [{"id": "findings", "type": "grid", "label": "Findings", "required": true, "rowDialog": true, "help": "One line per sub-section audited. Evidence = the record (form and date or lot), document, observation or person asked. Not applicable needs the reason.", "columns": [{"id": "clause", "label": "Clause", "type": "text", "required": true, "width": 1, "scanFact": "none"}, {"id": "result", "label": "Result", "type": "select", "required": true, "width": 1.3, "options": ["Compliant", "Minor non-conformance", "Major non-conformance", "Not applicable"]}, {"id": "evidence", "label": "Objective evidence seen", "type": "text", "required": true, "width": 3.5, "scanFact": "none"}, {"id": "capa_no", "label": "FRM-007 no.", "type": "text", "width": 1, "scanFact": "none"}], "rows": {"mode": "dynamic", "min": 1, "addLabel": "Add sub-section"}}]}, {"id": "follow_up", "title": "3. Results and follow-up", "fields": [{"id": "summary", "type": "textarea", "label": "Summary of the results", "required": true}, {"id": "capa_raised", "type": "select", "label": "Corrective action", "required": true, "options": ["No non-conformances found", "Every non-conformance is raised on FRM-007 - numbers in the table"]}, {"id": "communicated_to", "type": "textarea", "label": "Results told to", "required": true, "help": "Who was told - the staff who will carry out and verify each action - and when"}]}, {"id": "sign", "title": "4. Sign-off", "fields": [{"id": "auditor", "type": "signature", "label": "Auditor", "role": "filler", "required": true, "statement": "I audited the sections above. The results and the evidence recorded are what I found."}, {"id": "received_by", "type": "signature", "label": "Received by Senior Site Management", "role": "verifier", "required": true, "statement": "I have received these results and the corrective actions raised from them."}]}]}$q$::jsonb));

do $verify$
declare p jsonb; fs jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-038';
  if jsonb_array_length(p) <> 35 then
    raise exception 'FSQM-038 procedure is % lines, expected 35.', jsonb_array_length(p);
  end if;
  if (select count(*) from unnest(array['2.5.4.1 i', '2.5.4.1 ii', '2.5.4.1 iii', '2.5.4.1 iv', '2.5.4.2', '2.5.4.4']) c where p::text like '%' || c || '%') <> 6 then
    raise exception 'FSQM-038 does not cite every limb of 2.5.4.1, 2.5.4.2 and 2.5.4.4.';
  end if;
  if (select content::text from public.sop_documents where sop_number = 'FSQM-038') ~* 'Diana|Gabriela|Christina|GJM|Mercer' then
    raise exception 'FSQM-038 names a person; controlled documents name positions.';
  end if;
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-010';
  if (select count(*) from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f
       where f->>'id' in ('quarter', 'sections', 'findings', 'communicated_to', 'auditor', 'received_by')) <> 6 then
    raise exception 'FRM-010 is missing a required field.';
  end if;
  if (select jsonb_array_length(f->'options') from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f
       where f->>'id' = 'sections') <> 17 then
    raise exception 'FRM-010 does not list all 17 Code sections.';
  end if;
end $verify$;

commit;
